import { Injectable } from '@angular/core';
import { GoogleGenAI } from "@google/genai";

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    this.ai = new GoogleGenAI({ apiKey: process.env['API_KEY'] || '' });
  }

  async getBusinessAdvice(salesData: string): Promise<string> {
    try {
      if (!process.env['API_KEY']) {
        return "API Key မထည့်ထားပါ။ (No API Key found)";
      }

      const model = 'gemini-2.5-flash';
      const prompt = `
        You are a wise business advisor for a retail shop in Myanmar called 'Future World'.
        Analyze the following sales summary and give short, encouraging advice in Burmese language.
        Suggest 2 simple marketing ideas based on the items sold.

        Sales Summary:
        ${salesData}

        Response format:
        1. Analysis (In Burmese)
        2. Marketing Idea 1 (In Burmese)
        3. Marketing Idea 2 (In Burmese)
      `;

      const response = await this.ai.models.generateContent({
        model: model,
        contents: prompt,
      });

      return response.text;
    } catch (error) {
      console.error('AI Error:', error);
      return "AI စနစ် ချိတ်ဆက်၍မရပါ။ နောက်မှပြန်ကြိုးစားပါ။";
    }
  }

  async generateProductDescription(productName: string): Promise<string> {
    try {
        if (!process.env['API_KEY']) return "API Key Missing";

        const response = await this.ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: `Write a very short, catchy, futuristic product description (1 sentence) for '${productName}' in Burmese.`,
        });
        return response.text;
    } catch (e) {
        return "ဖော်ပြချက်မရရှိနိုင်ပါ။";
    }
  }
}

import { Injectable, signal, computed } from '@angular/core';

export interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  image: string;
  color: string;
}

export interface CartItem {
  product: Product;
  quantity: number;
}

export interface Order {
  id: string;
  date: Date;
  items: CartItem[];
  total: number;
}

@Injectable({
  providedIn: 'root'
})
export class PosService {
  // Initial Mock Data
  private initialProducts: Product[] = [
    { id: 1, name: 'Royal D', price: 500, category: 'Drinks', image: 'https://picsum.photos/200/200?random=1', color: 'bg-blue-600' },
    { id: 2, name: 'Myanmar Beer', price: 2500, category: 'Drinks', image: 'https://picsum.photos/200/200?random=2', color: 'bg-yellow-600' },
    { id: 3, name: 'Mama Noodle', price: 800, category: 'Food', image: 'https://picsum.photos/200/200?random=3', color: 'bg-red-600' },
    { id: 4, name: 'Sunflower Oil', price: 4500, category: 'Kitchen', image: 'https://picsum.photos/200/200?random=4', color: 'bg-yellow-500' },
    { id: 5, name: 'Toothpaste', price: 1200, category: 'Personal', image: 'https://picsum.photos/200/200?random=5', color: 'bg-green-500' },
    { id: 6, name: 'Coffee Mix', price: 200, category: 'Drinks', image: 'https://picsum.photos/200/200?random=6', color: 'bg-amber-700' },
    { id: 7, name: 'Notebook', price: 1500, category: 'Stationery', image: 'https://picsum.photos/200/200?random=7', color: 'bg-indigo-500' },
    { id: 8, name: 'Pen Set', price: 3000, category: 'Stationery', image: 'https://picsum.photos/200/200?random=8', color: 'bg-purple-600' },
  ];

  // State Signals
  products = signal<Product[]>(this.initialProducts);
  cart = signal<CartItem[]>([]);
  orders = signal<Order[]>([]);

  // Computed
  cartTotal = computed(() => {
    return this.cart().reduce((acc, item) => acc + (item.product.price * item.quantity), 0);
  });

  cartCount = computed(() => {
    return this.cart().reduce((acc, item) => acc + item.quantity, 0);
  });

  totalSalesToday = computed(() => {
      // Simplified: Just sums all orders for this demo
      return this.orders().reduce((acc, order) => acc + order.total, 0);
  });

  // Actions
  addToCart(product: Product) {
    this.cart.update(items => {
      const existing = items.find(i => i.product.id === product.id);
      if (existing) {
        return items.map(i => i.product.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...items, { product, quantity: 1 }];
    });
  }

  removeFromCart(productId: number) {
    this.cart.update(items => items.filter(i => i.product.id !== productId));
  }

  updateQuantity(productId: number, delta: number) {
    this.cart.update(items => {
      return items.map(item => {
        if (item.product.id === productId) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : item;
        }
        return item;
      });
    });
  }

  clearCart() {
    this.cart.set([]);
  }

  checkout() {
    const currentCart = this.cart();
    if (currentCart.length === 0) return;

    const newOrder: Order = {
      id: `ORD-${Date.now().toString().slice(-6)}`,
      date: new Date(),
      items: currentCart,
      total: this.cartTotal()
    };

    this.orders.update(orders => [newOrder, ...orders]);
    this.clearCart();
  }

  addProduct(product: Product) {
    this.products.update(p => [...p, product]);
  }
}

