import { Injectable, signal, computed, effect } from '@angular/core';

export interface Product {
  id: number;
  name: string;
  price: number;
  category: string;
  image: string;
}

export interface CartItem {
  product: Product;
  quantity: number;
}

export interface Order {
  id: string;
  date: string; // Changed to string for serialization
  items: CartItem[];
  total: number;
}

@Injectable({
  providedIn: 'root'
})
export class PosService {
  // Initial Mock Data (Only used if storage is empty)
  private initialProducts: Product[] = [
    { id: 1, name: 'Royal D', price: 500, category: 'Drinks', image: 'https://picsum.photos/200/200?random=1' },
    { id: 2, name: 'Myanmar Beer', price: 2500, category: 'Drinks', image: 'https://picsum.photos/200/200?random=2' },
    { id: 3, name: 'Mama Noodle', price: 800, category: 'Food', image: 'https://picsum.photos/200/200?random=3' },
    { id: 4, name: 'Sunflower Oil', price: 4500, category: 'Kitchen', image: 'https://picsum.photos/200/200?random=4' },
    { id: 5, name: 'Toothpaste', price: 1200, category: 'Personal', image: 'https://picsum.photos/200/200?random=5' },
    { id: 6, name: 'Coffee Mix', price: 200, category: 'Drinks', image: 'https://picsum.photos/200/200?random=6' },
  ];

  // State Signals
  products = signal<Product[]>(this.loadProducts());
  cart = signal<CartItem[]>([]);
  orders = signal<Order[]>(this.loadOrders());

  constructor() {
    // Auto-save whenever products or orders change
    effect(() => {
        localStorage.setItem('fw_products', JSON.stringify(this.products()));
    });
    effect(() => {
        localStorage.setItem('fw_orders', JSON.stringify(this.orders()));
    });
  }

  // Loaders
  private loadProducts(): Product[] {
    const stored = localStorage.getItem('fw_products');
    return stored ? JSON.parse(stored) : this.initialProducts;
  }

  private loadOrders(): Order[] {
    const stored = localStorage.getItem('fw_orders');
    return stored ? JSON.parse(stored) : [];
  }

  // Computed
  cartTotal = computed(() => {
    return this.cart().reduce((acc, item) => acc + (item.product.price * item.quantity), 0);
  });

  cartCount = computed(() => {
    return this.cart().reduce((acc, item) => acc + item.quantity, 0);
  });

  totalSalesToday = computed(() => {
      const today = new Date().toDateString();
      return this.orders()
        .filter(o => new Date(o.date).toDateString() === today)
        .reduce((acc, order) => acc + order.total, 0);
  });

  // Actions
  addToCart(product: Product) {
    this.cart.update(items => {
      const existing = items.find(i => i.product.id === product.id);
      if (existing) {
        return items.map(i => i.product.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...items, { product, quantity: 1 }];
    });
  }

  removeFromCart(productId: number) {
    this.cart.update(items => items.filter(i => i.product.id !== productId));
  }

  updateQuantity(productId: number, delta: number) {
    this.cart.update(items => {
      return items.map(item => {
        if (item.product.id === productId) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : item;
        }
        return item;
      });
    });
  }

  clearCart() {
    this.cart.set([]);
  }

  checkout(): Order | null {
    const currentCart = this.cart();
    if (currentCart.length === 0) return null;

    const newOrder: Order = {
      id: `INV-${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`,
      date: new Date().toISOString(),
      items: currentCart,
      total: this.cartTotal()
    };

    this.orders.update(orders => [newOrder, ...orders]);
    this.clearCart();
    return newOrder;
  }

  addNewProduct(name: string, price: number, category: string) {
    const newProduct: Product = {
        id: Date.now(),
        name,
        price,
        category,
        image: `https://picsum.photos/200/200?random=${Date.now()}` // Random image for simplicity
    };
    this.products.update(p => [...p, newProduct]);
  }

  resetSystem() {
      localStorage.removeItem('fw_orders');
      localStorage.removeItem('fw_products');
      location.reload();
  }
}

