export class PosTerminalComponent {
  posService = inject(PosService);
  searchTerm = signal('');
  selectedCategory = signal('All');

  // Modal States
  showAddProductModal = signal(false);
  lastOrder = signal<Order | null>(null);

  // Form Models
  newProductName = '';
  newProductPrice = 0;
  newProductCategory = 'Other';

  filteredProducts = computed(() => {
    const term = this.searchTerm().toLowerCase();
    const category = this.selectedCategory();

    return this.posService.products().filter(p => {
      const matchesSearch = p.name.toLowerCase().includes(term);
      const matchesCategory = category === 'All' || p.category === category;
      return matchesSearch && matchesCategory;
    });
  });

  handleCheckout() {
    if(confirm('ငွေချေမှာ သေချာပါသလား?')) {
        const order = this.posService.checkout();
        if (order) {
            this.lastOrder.set(order);
        }
    }
  }

  submitNewProduct() {
      if (this.newProductName && this.newProductPrice > 0) {
          this.posService.addNewProduct(this.newProductName, this.newProductPrice, this.newProductCategory);
          // Reset form
          this.newProductName = '';
          this.newProductPrice = 0;
          this.newProductCategory = 'Other';
          this.showAddProductModal.set(false);
      } else {
          alert('ကျေးဇူးပြု၍ အချက်အလက်များကို ပြည့်စုံစွာဖြည့်ပါ');
      }
  }
}

