import { Injectable, signal, computed, effect } from '@angular/core';

export interface Product {
  id: number;
  barcode: string; // Added barcode
  name: string;
  price: number; // Base price in MMK
  category: string;
  image: string;
}

export interface CartItem {
  product: Product;
  quantity: number;
}

export interface Order {
  id: string;
  date: string;
  items: CartItem[];
  total: number;
  paymentMethod: 'Cash' | 'KBZ Pay' | 'Wave Pay'; // Added payment method
  currency: 'MMK' | 'THB' | 'CNY'; // Recorded currency
}

@Injectable({
  providedIn: 'root'
})
export class PosService {
  // Exchange Rates (Base: 1 Unit = ? MMK)
  // Example: 1 THB = 100 MMK, 1 CNY = 450 MMK
  private exchangeRates = {
    MMK: 1,
    THB: 100,
    CNY: 450
  };

  // Initial Mock Data
  private initialProducts: Product[] = [
    { id: 1, barcode: '8850123', name: 'Royal D', price: 500, category: 'Drinks', image: 'https://picsum.photos/200/200?random=1' },
    { id: 2, barcode: '8850124', name: 'Myanmar Beer', price: 2500, category: 'Drinks', image: 'https://picsum.photos/200/200?random=2' },
    { id: 3, barcode: '8850125', name: 'Mama Noodle', price: 800, category: 'Food', image: 'https://picsum.photos/200/200?random=3' },
    { id: 4, barcode: '8850126', name: 'Sunflower Oil', price: 4500, category: 'Kitchen', image: 'https://picsum.photos/200/200?random=4' },
    { id: 5, barcode: '8850127', name: 'Toothpaste', price: 1200, category: 'Personal', image: 'https://picsum.photos/200/200?random=5' },
    { id: 6, barcode: '8850128', name: 'Coffee Mix', price: 200, category: 'Drinks', image: 'https://picsum.photos/200/200?random=6' },
  ];

  // State Signals
  products = signal<Product[]>(this.loadProducts());
  cart = signal<CartItem[]>([]);
  orders = signal<Order[]>(this.loadOrders());

  // Currency State
  activeCurrency = signal<'MMK' | 'THB' | 'CNY'>('MMK');

  constructor() {
    effect(() => localStorage.setItem('fw_products', JSON.stringify(this.products())));
    effect(() => localStorage.setItem('fw_orders', JSON.stringify(this.orders())));
  }

  // Loaders
  private loadProducts(): Product[] {
    const stored = localStorage.getItem('fw_products');
    return stored ? JSON.parse(stored) : this.initialProducts;
  }

  private loadOrders(): Order[] {
    const stored = localStorage.getItem('fw_orders');
    return stored ? JSON.parse(stored) : [];
  }

  // Computed
  cartTotalMMK = computed(() => {
    return this.cart().reduce((acc, item) => acc + (item.product.price * item.quantity), 0);
  });

  cartCount = computed(() => {
    return this.cart().reduce((acc, item) => acc + item.quantity, 0);
  });

  totalSalesToday = computed(() => {
      const today = new Date().toDateString();
      return this.orders()
        .filter(o => new Date(o.date).toDateString() === today)
        .reduce((acc, order) => acc + order.total, 0); // Logic simplifies to MMK total for analytics
  });

  // Helpers
  convertPrice(priceMMK: number): number {
      const rate = this.exchangeRates[this.activeCurrency()];
      // MMK to Foreign: Divide by rate
      // If MMK: 500 / 1 = 500
      // If THB: 500 / 100 = 5
      return Math.ceil(priceMMK / rate); 
  }

  getCurrencySymbol(): string {
      switch(this.activeCurrency()) {
          case 'MMK': return 'Ks';
          case 'THB': return '฿';
          case 'CNY': return '¥';
      }
  }

  // Actions
  addToCart(product: Product) {
    this.cart.update(items => {
      const existing = items.find(i => i.product.id === product.id);
      if (existing) {
        return items.map(i => i.product.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...items, { product, quantity: 1 }];
    });
  }

  addToCartByBarcode(barcode: string): boolean {
      const product = this.products().find(p => p.barcode === barcode);
      if (product) {
          this.addToCart(product);
          return true;
      }
      return false;
  }

  removeFromCart(productId: number) {
    this.cart.update(items => items.filter(i => i.product.id !== productId));
  }

  updateQuantity(productId: number, delta: number) {
    this.cart.update(items => {
      return items.map(item => {
        if (item.product.id === productId) {
          const newQty = item.quantity + delta;
          return newQty > 0 ? { ...item, quantity: newQty } : item;
        }
        return item;
      });
    });
  }

  clearCart() {
    this.cart.set([]);
  }

  checkout(paymentMethod: 'Cash' | 'KBZ Pay' | 'Wave Pay'): Order | null {
    const currentCart = this.cart();
    if (currentCart.length === 0) return null;

    const newOrder: Order = {
      id: `INV-${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`,
      date: new Date().toISOString(),
      items: currentCart,
      total: this.cartTotalMMK(),
      paymentMethod,
      currency: 'MMK' // Storing base currency for consistency
    };

    this.orders.update(orders => [newOrder, ...orders]);
    this.clearCart();
    return newOrder;
  }

