export class DashboardComponent {
  posService = inject(PosService);
  geminiService = inject(GeminiService);

  aiResponse = signal<string>('');
  isLoadingAi = signal<boolean>(false);
  inputLicenseKey = '';

  getOrderItemsSummary(order: any): string {
      return order.items.map((i: any) => i.product.name).join(', ').slice(0, 30) + (order.items.length > 2 ? '...' : '');
  }

  async askAi() {
    this.isLoadingAi.set(true);
    const salesSummary = `
      Total Sales Today: ${this.posService.totalSalesToday()} MMK.
      Total Transactions: ${this.posService.orders().length}.
      Products Sold: ${this.posService.orders().map(o => o.items.map(i => i.product.name).join(', ')).join(', ')}.
    `;

    const advice = await this.geminiService.getBusinessAdvice(salesSummary);
    this.aiResponse.set(advice);
    this.isLoadingAi.set(false);
  }

  activateLicense() {
      if(this.posService.activateLicense(this.inputLicenseKey)) {
          alert('License Activated Successfully! Thank you.');
          this.inputLicenseKey = '';
      } else {
          alert('Invalid License Key');
      }
  }

  handleFileImport(event: any) {
      const file = event.target.files[0];
      if(file) {
          if(confirm('Data Restore လုပ်လိုက်လျှင် လက်ရှိစာရင်းများ ပျောက်သွားနိုင်ပါသည်။ ဆက်လုပ်မည်လား?')) {
              this.posService.importData(file).then(success => {
                  if(success) alert('Data Restored Successfully!');
                  else alert('Invalid Backup File');
              });
          }
      }
  }

  handleReset() {
      if(confirm('သတိပြုရန်! စာရင်းများအားလုံး ဖျက်ပစ်မည်မှာ သေချာပါသလား? ပြန်ယူ၍ မရနိုင်ပါ။')) {
          this.posService.resetSystem();
      }
  }
}

import { Injectable, signal, computed, effect } from '@angular/core';

export interface Product {
  id: number;
  barcode: string;
  name: string;
  price: number;
  category: string;
  image: string; // Base64 string or URL
  stock: number;
}

export interface CartItem {
  product: Product;
  quantity: number;
}

export interface Order {
  id: string;
  date: string;
  items: CartItem[];
  total: number;
  paymentMethod: 'Cash' | 'KBZ Pay' | 'Wave Pay';
  currency: 'MMK' | 'THB' | 'CNY';
}

@Injectable({
  providedIn: 'root'
})
export class PosService {
  private exchangeRates = {
    MMK: 1,
    THB: 100,
    CNY: 450
  };

  // Mock initial data
  private initialProducts: Product[] = [
    { id: 1, barcode: '8850123', name: 'Royal D', price: 500, category: 'Drinks', image: 'https://picsum.photos/200/200?random=1', stock: 50 },
    { id: 2, barcode: '8850124', name: 'Myanmar Beer', price: 2500, category: 'Drinks', image: 'https://picsum.photos/200/200?random=2', stock: 24 },
  ];

  products = signal<Product[]>([]);
  cart = signal<CartItem[]>([]);
  orders = signal<Order[]>([]);
  activeCurrency = signal<'MMK' | 'THB' | 'CNY'>('MMK');

  // Licensing State
  licenseKey = signal<string>(localStorage.getItem('fw_license') || '');

  // Admin Secret Key (Editable) - Default: MasterSaiYan
  adminSecret = signal<string>(localStorage.getItem('fw_admin_secret') || 'MasterSaiYan');

  // Check if license key matches the admin secret
  isProVersion = computed(() => this.licenseKey() === this.adminSecret());

  constructor() {
    this.loadData();

    // Auto-save effects
    effect(() => localStorage.setItem('fw_products', JSON.stringify(this.products())));
    effect(() => localStorage.setItem('fw_orders', JSON.stringify(this.orders())));
    effect(() => localStorage.setItem('fw_license', this.licenseKey()));
    effect(() => localStorage.setItem('fw_admin_secret', this.adminSecret()));
  }

  private loadData() {
    const p = localStorage.getItem('fw_products');
    const o = localStorage.getItem('fw_orders');

    if (p) {
        this.products.set(JSON.parse(p));
    } else {
        this.products.set(this.initialProducts);
    }

    if (o) {
        this.orders.set(JSON.parse(o));
    }
  }

  // --- Calculations ---
  cartTotalMMK = computed(() => {
    return this.cart().reduce((acc, item) => acc + (item.product.price * item.quantity), 0);
  });

  cartCount = computed(() => {
    return this.cart().reduce((acc, item) => acc + item.quantity, 0);
  });

  totalSalesToday = computed(() => {
      const today = new Date().toDateString();
      return this.orders()
        .filter(o => new Date(o.date).toDateString() === today)
        .reduce((acc, order) => acc + order.total, 0);
  });

  // --- Currency Helpers ---
  convertPrice(priceMMK: number): number {
      const rate = this.exchangeRates[this.activeCurrency()];
      return Math.ceil(priceMMK / rate); 
  }

  getCurrencySymbol(): string {
      switch(this.activeCurrency()) {
          case 'MMK': return 'Ks';
          case 'THB': return '฿';
          case 'CNY': return '¥';
      }
  }

  // --- Cart Actions ---
  addToCart(product: Product) {
    if (product.stock <= 0) return;

    this.cart.update(items => {
      const existing = items.find(i => i.product.id === product.id);
      if (existing) {
          if (existing.quantity >= product.stock) return items;
          return items.map(i => i.product.id === product.id ? { ...i, quantity: i.quantity + 1 } : i);
      }
      return [...items, { product, quantity: 1 }];
    });
  }

  addToCartByBarcode(barcode: string): boolean {
      const product = this.products().find(p => p.barcode === barcode);
      if (product && product.stock > 0) {
          this.addToCart(product);
          return true;
      }
      return false;
  }

  removeFromCart(productId: number) {
    this.cart.update(items => items.filter(i => i.product.id !== productId));
  }

  updateQuantity(productId: number, delta: number) {
    this.cart.update(items => {
      return items.map(item => {
        if (item.product.id === productId) {
          const newQty = item.quantity + delta;
          if (newQty > item.product.stock) return item; 
          return newQty > 0 ? { ...item, quantity: newQty } : item;
        }
        return item;
      });
    });
  }

  clearCart() {
    this.cart.set([]);
  }

  checkout(paymentMethod: 'Cash' | 'KBZ Pay' | 'Wave Pay'): Order | null {
    const currentCart = this.cart();
    if (currentCart.length === 0) return null;

    // Deduct Stock
    this.products.update(allProducts => {
        return allProducts.map(p => {
            const cartItem = currentCart.find(c => c.product.id === p.id);
            if (cartItem) {
                return { ...p, stock: Math.max(0, p.stock - cartItem.quantity) };
            }
            return p;
        });
    });

    const newOrder: Order = {
      id: `INV-${Math.floor(Math.random() * 10000).toString().padStart(4, '0')}`,
      date: new Date().toISOString(),
      items: currentCart,
      total: this.cartTotalMMK(),
      paymentMethod,
      currency: 'MMK'
    };

    this.orders.update(orders => [newOrder, ...orders]);
    this.clearCart();
    return newOrder;
  }

  // --- Product Management ---

  addNewProduct(name: string, price: number, category: string, barcode: string, stock: number, imageBase64: string) {
    // Basic limit for Free version
    if (!this.isProVersion() && this.products().length >= 5) {
        alert("Free Version တွင် ပစ္စည်း ၅ မျိုးသာ ထည့်သွင်းခွင့်ရှိသည်။ အကန့်အသတ်မရှိသုံးရန် လိုင်စင်ဝယ်ယူပါ။");
        return;
    }

    const newProduct: Product = {
        id: Date.now(),
        barcode: barcode || Date.now().toString(),
        name,
        price,
        category,
        stock,
        image: imageBase64 || `https://picsum.photos/200/200?random=${Date.now()}`
    };
    this.products.update(p => [...p, newProduct]);
  }

  updateProduct(updatedProduct: Product) {
      this.products.update(products => 
        products.map(p => p.id === updatedProduct.id ? updatedProduct : p)
      );
      this.cart.update(items => 
        items.map(item => item.product.id === updatedProduct.id ? { ...item, product: updatedProduct } : item)
      );
  }

  deleteProduct(id: number) {
      this.products.update(products => products.filter(p => p.id !== id));
      this.removeFromCart(id);
  }

  // --- System Data Management ---

  activateLicense(key: string): boolean {
      if (key === this.adminSecret()) {
          this.licenseKey.set(key);
          return true;
      }
      return false;
  }

  // New method to change the secret key
  updateAdminSecret(newSecret: string) {
      this.adminSecret.set(newSecret);
  }

  exportData() {
      const data = {
          products: this.products(),
          orders: this.orders(),
          license: this.licenseKey(),
          version: '1.0'
      };
      const blob = new Blob([JSON.stringify(data)], { type: 'application/json' });
      const url = window.URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `FutureWorld_Backup_${new Date().toISOString().split('T')[0]}.json`;
      a.click();
      window.URL.revokeObjectURL(url);
  }

  importData(file: File): Promise<boolean> {
      return new Promise((resolve) => {
          const reader = new FileReader();
          reader.onload = (e: any) => {
              try {
                  const data = JSON.parse(e.target.result);
                  if (data.products && data.orders) {
                      this.products.set(data.products);
                      this.orders.set(data.orders);
                      if(data.license) this.licenseKey.set(data.license);
                      resolve(true);
                  } else {
                      resolve(false);
                  }
              } catch (err) {
                  resolve(false);
              }
          };
          reader.readAsText(file);
      });
  }

  resetSystem() {
      localStorage.clear();
      location.reload();
  }
}

