    </div>
  `,
  styles: [`
    .custom-scroll::-webkit-scrollbar { width: 4px; }
    .custom-scroll::-webkit-scrollbar-thumb { background: #374151; border-radius: 2px; }
  `]
})
export class DashboardComponent {
  posService = inject(PosService);

  // Client Activation Model
  inputLicenseKey = '';

  // Shop Config Models
  shopName = '';
  shopAddress = '';
  shopPhone = '';
  shopFooter = '';

  // Admin Panel Models
  authAdminPassword = '';
  adminNewLicenseKey = '';
  adminNewPassword = '';

  constructor() {
      const info = this.posService.shopInfo();
      this.shopName = info.name;
      this.shopAddress = info.address;
      this.shopPhone = info.phone;
      this.shopFooter = info.footerMessage;
  }

  getOrderItemsSummary(order: any): string {
      return order.items.map((i: any) => i.product.name).join(', ').slice(0, 30) + (order.items.length > 2 ? '...' : '');
  }

  voidOrder(id: string) {
      if(confirm('ဤဘေလ်ကို ဖျက်မည်မှာ သေချာပါသလား? Stock များပြန်လည်ဖြည့်သွင်းသွားပါမည်။')) {
          this.posService.voidOrder(id);
      }
  }

  // Shop Config
  saveShopSettings() {
      this.posService.updateShopInfo({
          name: this.shopName,
          address: this.shopAddress,
          phone: this.shopPhone,
          footerMessage: this.shopFooter
      });
      alert('ဆိုင်အချက်အလက်များ သိမ်းဆည်းပြီးပါပြီ။');
  }

  // Client Action
  activateLicense() {
      if(this.posService.attemptActivation(this.inputLicenseKey)) {
          alert('License Activated Successfully!');
          this.inputLicenseKey = '';
      } else {
          alert('Invalid License Key');
      }
  }

  // Admin Action
  saveAdminSettings() {
      if (!this.authAdminPassword) {
          alert('Please enter your current Admin Password to save changes.');
          return;
      }

      const success = this.posService.updateSystemSettings(
          this.authAdminPassword, 
          this.adminNewLicenseKey || undefined, 
          this.adminNewPassword || undefined
      );

      if (success) {
          alert('Settings Saved Successfully!');
          this.authAdminPassword = '';
          this.adminNewLicenseKey = '';
          this.adminNewPassword = '';
      } else {
          alert('Incorrect Admin Password!');
      }
  }

  handleReset() {
      if (!this.authAdminPassword) {
          alert('Please enter Admin Password to perform a reset.');
          return;
      }
      if(confirm('Warning: This will delete ALL sales and product data. Are you sure?')) {
          const success = this.posService.resetSystem(this.authAdminPassword);
          if(!success) {
              alert('Incorrect Admin Password!');
          }
      }
  }

  handleFileImport(event: any) {
      const file = event.target.files[0];
      if(file) {
          if(confirm('Data Restore လုပ်လိုက်လျှင် လက်ရှိစာရင်းများ ပျောက်သွားနိုင်ပါသည်။ ဆက်လုပ်မည်လား?')) {
              this.posService.importData(file).then(success => {
                  if(success) alert('Data Restored Successfully!');
                  else alert('Invalid Backup File');
              });
          }
      }
  }
}

import { Injectable } from '@angular/core';
import { GoogleGenAI } from "@google/genai";

@Injectable({
  providedIn: 'root'
})
export class GeminiService {
  private ai: GoogleGenAI;

  constructor() {
    let apiKey = '';
    // Safety check: process.env might not be available in all build environments (like window apps)
    try {
        if (typeof process !== 'undefined' && process.env) {
            apiKey = process.env['API_KEY'] || '';
        }
    } catch (e) {
        console.warn('AI Service: Environment variables not accessible.');
    }
    this.ai = new GoogleGenAI({ apiKey });
  }

  async getBusinessAdvice(salesData: string): Promise<string> {
    try {
      // Safety check again
      let apiKey = '';
      if (typeof process !== 'undefined' && process.env) {
          apiKey = process.env['API_KEY'] || '';
      }

      if (!apiKey) {
        return "API Key မထည့်ထားပါ။ (No API Key found)";
      }

      const model = 'gemini-2.5-flash';
      const prompt = `
        You are a wise business advisor for a retail shop in Myanmar called 'Future World'.
        Analyze the following sales summary and give short, encouraging advice in Burmese language.
        Suggest 2 simple marketing ideas based on the items sold.

        Sales Summary:
        ${salesData}

        Response format:
        1. Analysis (In Burmese)
        2. Marketing Idea 1 (In Burmese)
        3. Marketing Idea 2 (In Burmese)
      `;

      const response = await this.ai.models.generateContent({
        model: model,
        contents: prompt,
      });

      return response.text || "အကြံဉာဏ်မရရှိနိုင်ပါ။";
    } catch (error) {
      console.error('AI Error:', error);
      return "AI စနစ် ချိတ်ဆက်၍မရပါ။ နောက်မှပြန်ကြိုးစားပါ။";
    }
  }

  async generateProductDescription(productName: string): Promise<string> {
    try {
        let apiKey = '';
        if (typeof process !== 'undefined' && process.env) {
            apiKey = process.env['API_KEY'] || '';
        }
        if (!apiKey) return "API Key Missing";

        const response = await this.ai.models.generateContent({
            model: 'gemini-2.5-flash',
            contents: `Write a very short, catchy, futuristic product description (1 sentence) for '${productName}' in Burmese.`,
        });
        return response.text || "ဖော်ပြချက်မရရှိနိုင်ပါ။";
    } catch (e) {
        return "ဖော်ပြချက်မရရှိနိုင်ပါ။";
    }
  }
}

